```python
def is_prime(num):
    if num < 2:
        return False
    for i in range(2, num + 1):
        if num % i == 0:
            return False
    return True

def count_primes(n):
    count = 0
    for num in range(2, n + 1):
        if is_prime(num):
            count += 1
    return count
